/* ---------- Marked og posisjon ----------
   Et verktøy for dokumenterte sammenligninger. Ingenting hentes fra nettet. Alt er registrert for hånd, med kilde.
   Ingen rangering lages av seg selv: et alternativ plasseres i kartet bare når absolutte krav er dokumentert oppfylt
   og hele prisen kan regnes ut på samme grunnlag. Ukjent pris blir aldri null, og ukjent egenskap blir aldri «nei». */
VIEWS.splice(VIEWS.findIndex(v=>v.k==='stat')+1,0,{k:'marked',n:'Marked og posisjon',g:'Verktøy'});
ICON.marked='<path d="M3 3v18h18"/><circle cx="8" cy="15" r="2"/><circle cx="13" cy="8.5" r="2"/><circle cx="18" cy="12.5" r="2"/>';
VDESC.marked='Dokumenterte sammenligninger, salgsargumenter og læring fra egne saker';
FORM_VIEWS.push('marked'); FNAME.learn='Læring fra saken';
S.mscen=S.mscen||{}; S.malts=S.malts||{}; S.mpos=S.mpos||{};
UI.mk={tab:'sammenlign',scen:'',edit:false,sel:'',ed:null,pos:null,posF:'alle',per:'12m',busy:false,aiErr:''};
const MK_NEEDS=[['cap','Plass til deltakerantallet'],['step','Trinnfri adkomst'],['mics','Trådløse mikrofoner'],['proj','Projektor eller storskjerm'],['stream','Strømming'],['tech','Tekniker til stede'],['stage','Scene'],['cater','Servering i lokalet'],['foyer','Eget mingleareal'],['day','Dagslys'],['books','Boksalg mulig'],['eve','Kveldsarrangement mulig']];
const MK_SRC={nettsted:'Opplyst på leverandørens nettsted',tilbud:'Opplyst i et tilbud',kunde:'Kundens utsagn',intern:'Intern vurdering'}, MK_DOC=['nettsted','tilbud'];
const MK_CAT={rom:'Rom',teknikk:'Teknikk',personell:'Personell',servering:'Servering',tillegg:'Tillegg',minimum:'Minimumsleie'};
const MK_PST={bekreftet:'Bekreftet pris',beregnet:'Dokumentert beregning',innhentes:'Må innhentes',inkludert:'Inkludert i annen linje'};
const MK_UNIT={fast:'fast beløp',time:'per time',person:'per deltaker'};
const MK_REASON={pris:'Pris',ledighet:'Manglende ledighet',kapasitet:'Kapasitet eller oppsett',beliggenhet:'Beliggenhet',teknikk:'Teknikk eller servering',utsatt:'Utsatt arrangement',ukjent:'Ukjent'};
const MK_SUPER=/(?<![a-zæøå])(unik|unikt|unike|best|beste|billigst|billigste|rimeligst|rimeligste|størst|største|eneste|ledende|overlegen|overlegent|markedsleder|nummer én|nr\.? ?1|uslåelig)(?![a-zæøå])/i;
const mkL=c=>Object.entries(S[c]||{}).filter(([,x])=>x&&!x.deletedAt).map(([id,x])=>({id,...x}));
const mkNeedLabel=n=>n.label||(MK_NEEDS.find(x=>x[0]===n.key)||[])[1]||n.key;
const mkNeeds=sc=>(sc.needs||[]).map(n=>({key:n.key,label:mkNeedLabel(n),must:!!n.must}));
const mkSrc=(alt,sid)=>sid?((alt.sources||{})[sid]||null):null;
const mkIsDoc=s=>!!(s&&MK_DOC.includes(s.kind)&&String(s.ref||'').trim());
const mkSrcTxt=s=>s?MK_SRC[s.kind]+(s.ref?': '+s.ref:'')+(s.checkedAt?', kontrollert '+fdt(s.checkedAt):', kontrolltidspunkt ikke registrert')+(s.validTo?', gyldig til '+fdt(s.validTo):''):'Ingen kilde registrert';
/* én egenskap for ett alternativ. doc betyr: ja eller nei er opplyst på leverandørens nettsted eller i et tilbud, med kildehenvisning. */
function mkProp(sc,alt,key){
  if(key==='cap'){ const n=Number(sc.attendees)||0, s=mkSrc(alt,alt.capSrc), max=Number(alt.capMax)||0;
    if(!n) return {v:'ukjent',doc:false,src:s,note:'Scenarioet mangler deltakerantall'};
    if(!max) return {v:'ukjent',doc:false,src:s,note:'Kapasitet er ikke registrert'};
    return {v:n<=max?'ja':'nei',doc:mkIsDoc(s),src:s,note:'Kapasitet inntil '+max+(alt.capNote?' ('+alt.capNote+')':'')+'. Scenarioet har '+n}; }
  const p=(alt.props||{})[key]||{v:'ukjent'}, s=mkSrc(alt,p.src); return {v:p.v||'ukjent',doc:(p.v==='ja'||p.v==='nei')&&mkIsDoc(s),src:s,note:p.note||''};
}
/* prisen regnes for scenarioet: samme varighet, samme deltakerantall, samme avgiftsgrunnlag. Mangler noe, blir det ingen sum. */
function mkPrice(sc,alt){
  const lines=[], miss=[], today=new Date().toISOString().slice(0,10), need=['rom'].concat(String(sc.tech||'').trim()?['teknikk']:[],String(sc.catering||'').trim()?['servering']:[]);
  let rest=0, rom=0, calc=false, minimum=null, minApplied=false;
  for(const c of (alt.price||[])){ const s=mkSrc(alt,c.src), nm=MK_CAT[c.k]+(c.label?' «'+c.label+'»':''), L={...c,srcO:s,scen:null,flags:[]}; lines.push(L);
    if(c.status==='inkludert') continue;
    if(c.status==='innhentes'||c.amount===''||c.amount==null||isNaN(Number(c.amount))){ L.flags.push('må innhentes'); miss.push(nm+': prisen må innhentes'); continue; }
    if(!mkIsDoc(s)){ L.flags.push('ikke dokumentert'); miss.push(nm+': prisen har ikke dokumentert kilde ('+(s?MK_SRC[s.kind].toLowerCase():'ingen kilde')+')'); continue; }
    if(s.validTo&&s.validTo<today){ L.flags.push('historisk pris'); miss.push(nm+': prisen gjaldt til '+fdt(s.validTo)+'. Historiske priser er ikke automatisk gjeldende'); continue; }
    if(c.unit==='time'&&!(Number(sc.hours)>0)){ L.flags.push('mangler varighet'); miss.push(nm+': prisen er per time, og scenarioet mangler varighet'); continue; }
    if(c.unit==='person'&&!(Number(sc.attendees)>0)){ L.flags.push('mangler deltakerantall'); miss.push(nm+': prisen er per deltaker, og scenarioet mangler deltakerantall'); continue; }
    let a=Number(c.amount)*(c.unit==='time'?Number(sc.hours):c.unit==='person'?Number(sc.attendees):1); if(c.unit==='time'||c.unit==='person'){ calc=true; L.flags.push(nf.format(Number(c.amount))+' kr × '+(c.unit==='time'?sc.hours+' timer':sc.attendees+' deltakere')); }
    if(c.basis!=='eks'&&c.basis!=='inkl'){ L.flags.push('avgiftsgrunnlag ukjent'); miss.push(nm+': det er ikke opplyst om prisen er med eller uten mva'); continue; }
    if(c.basis!==sc.vat){ const pct=Number(c.vatPct); if(!(pct>0)){ L.flags.push('kan ikke regnes om'); miss.push(nm+': prisen er oppgitt '+(c.basis==='eks'?'eks.':'inkl.')+' mva, og satsen er ikke dokumentert. Den kan ikke regnes om'); continue; } a=sc.vat==='eks'?a/(1+pct/100):a*(1+pct/100); calc=true; L.flags.push('regnet om med '+pct+' % mva'); }
    if(c.status==='beregnet') calc=true; L.scen=a;
    if(c.k==='minimum'){ minimum=a; continue; } if(c.k==='rom') rom+=a; else rest+=a; }
  for(const k of need) if(!lines.some(l=>l.k===k&&(l.status==='inkludert'||l.scen!=null))&&!lines.some(l=>l.k===k)) miss.push('Pris for '+MK_CAT[k].toLowerCase()+' er ikke registrert og må innhentes');
  if(minimum!=null&&rom<minimum&&lines.some(l=>l.k==='rom'&&l.scen!=null)){ rom=minimum; minApplied=true; calc=true; }
  const ok=!miss.length&&lines.some(l=>l.scen!=null);
  return {lines,miss:[...new Set(miss)],need,total:ok?Math.round(rom+rest):null,status:!ok?'innhentes':calc?'beregnet':'bekreftet',minApplied,minimum};
}
function mkEval(sc,alt){
  const needs=mkNeeds(sc).map(n=>({...n,...mkProp(sc,alt,n.key)})), P=mkPrice(sc,alt), known=n=>n.doc&&(n.v==='ja'||n.v==='nei');
  const mustNo=needs.filter(n=>n.must&&n.v==='nei'&&n.doc), mustOpen=needs.filter(n=>n.must&&!known(n)), why=[]; let place='kart';
  if(mustNo.length){ place='uaktuell'; for(const n of mustNo) why.push('Oppfyller ikke absolutt krav: '+n.label+(n.note?'. '+n.note:'')); }
  else { for(const n of mustOpen) why.push('Absolutt krav er ikke dokumentert: '+n.label+(n.v!=='ukjent'?' ('+(n.src?MK_SRC[n.src.kind].toLowerCase():'uten kilde')+' sier '+n.v+')':'')); for(const m of P.miss) why.push(m); if(why.length) place='avklares'; }
  return {alt,needs,nDoc:needs.filter(n=>n.v==='ja'&&n.doc).length,nChosen:needs.length,unk:needs.filter(n=>!known(n)).length,P,place,why,planned:!!alt.planned};
}
function mkScen(){ const L=mkL('mscen'); return L.find(s=>s.id===UI.mk.scen)||null; }
function mkEvals(sc){ return (sc.altIds||[]).map(id=>S.malts[id]&&!S.malts[id].deletedAt?mkEval(sc,{id,...S.malts[id]}):null).filter(Boolean); }
/* generisk behovsbeskrivelse til bruk utenfor Salong: aldri kundenavn, sakstittel, notater eller priser */
function mkGeneric(sc){ const d=sc.dealId?S.deals[sc.dealId]:null, hide=[d&&orgName(d.orgId),d&&d.title].filter(x=>x&&x.length>2), per=sc.date&&/^\d{4}-\d{2}/.test(sc.date)?new Date(sc.date.slice(0,7)+'-15').toLocaleDateString('nb-NO',{month:'long',year:'numeric'}):'';
  let t='Lokale til arrangement'+(sc.attendees?' for '+sc.attendees+' deltakere':'')+(sc.setup?', oppsett '+String(sc.setup).toLowerCase():'')+(sc.hours?', varighet '+sc.hours+' timer':'')+(per?', '+per:'')+'.'+(String(sc.tech||'').trim()?' Teknikk: '+sc.tech.trim()+'.':'')+(String(sc.catering||'').trim()?' Servering: '+sc.catering.trim()+'.':'')+(mkNeeds(sc).length?' Viktige behov: '+mkNeeds(sc).map(n=>n.label.toLowerCase()+(n.must?' (krav)':'')).join(', ')+'.':'');
  for(const h of hide) t=t.split(h).join('[fjernet]'); return t; }
function mkHours(t){ const m=String(t||'').match(/(\d{1,2})[:.](\d{2})\s*[–-]\s*(\d{1,2})[:.](\d{2})/); if(!m) return ''; const h=(+m[3]*60+ +m[4]-(+m[1]*60+ +m[2]))/60; return h>0?String(Math.round(h*2)/2):''; }

/* ---------- pris–behov-kartet ---------- */
function mkChart(E,sc){
  const pts=E.filter(e=>e.place==='kart'), N=mkNeeds(sc).length; if(!pts.length||!N) return '';
  const W=Math.max(300,Math.min(860,(($('#view')?.clientWidth)||860)-40)), H=Math.round(Math.min(340,Math.max(230,W*.42))), m={l:46,r:26,t:14,b:44}, iw=W-m.l-m.r, ih=H-m.t-m.b;
  const mx=Math.max(...pts.map(e=>e.P.total)), step=[500,1000,2000,2500,5000,10000,20000,25000,50000,100000].find(s=>mx/s<=6)||200000, xmax=Math.max(step,Math.ceil(mx*1.08/step)*step);
  const x=v=>m.l+v/xmax*iw, y=v=>m.t+ih-(v/N)*ih, seen={};
  let g='';
  for(let v=0;v<=xmax;v+=step) g+='<line class="mk-grid" x1="'+x(v)+'" x2="'+x(v)+'" y1="'+m.t+'" y2="'+(m.t+ih)+'"/><text class="mk-tick" x="'+x(v)+'" y="'+(m.t+ih+16)+'" text-anchor="middle">'+(v>=1000?nf.format(v/1000)+' k':v)+'</text>';
  for(let v=0;v<=N;v++) g+='<line class="mk-grid" x1="'+m.l+'" x2="'+(m.l+iw)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text class="mk-tick" x="'+(m.l-8)+'" y="'+(y(v)+4)+'" text-anchor="end">'+v+'</text>';
  g+='<text class="mk-axt" x="'+(m.l+iw/2)+'" y="'+(H-6)+'" text-anchor="middle">Sammenlignbar totalpris for scenarioet, kr '+(sc.vat==='inkl'?'inkl.':'eks.')+' mva</text><text class="mk-axt" transform="translate(12 '+(m.t+ih/2)+') rotate(-90)" text-anchor="middle">Dokumentert oppfylte behov</text>';
  let marks='', hits='', labels='';
  pts.forEach((e,i)=>{ const k=e.P.total+'|'+e.nDoc, off=(seen[k]=(seen[k]||0)+1)-1, cx=x(e.P.total)+off*16, cy=y(e.nDoc), own=!!e.alt.own, sel=UI.mk.sel===e.alt.id, nm=e.alt.supplier+' · '+e.alt.name;
    marks+=(sel?'<circle class="mk-sel" cx="'+cx+'" cy="'+cy+'" r="12"/>':'')+'<circle class="mk-pt'+(own?' own':'')+(e.planned?' plan':'')+'" cx="'+cx+'" cy="'+cy+'" r="'+(own?7:6)+'"/>';
    if(own||sel||pts.length<=4){ const right=cx+14+nm.length*6.3<W-4; labels+='<text class="mk-lab" x="'+(right?cx+13:cx-13)+'" y="'+(cy-10<m.t+8?cy+18:cy-9)+'" text-anchor="'+(right?'start':'end')+'">'+esc(nm)+'</text>'; }
    hits+='<circle class="mk-hit" cx="'+cx+'" cy="'+cy+'" r="15" tabindex="0" role="button" data-mkpt="'+esc(e.alt.id)+'" aria-pressed="'+sel+'" aria-label="'+esc(nm+(e.planned?', planlagt lokale':'')+'. Totalpris '+kr(e.P.total)+', '+MK_PST[e.P.status].toLowerCase()+'. '+e.nDoc+' av '+e.nChosen+' valgte behov dokumentert oppfylt. Trykk for detaljer.')+'" data-n="'+esc(nm)+'" data-p="'+esc(kr(e.P.total)+' · '+MK_PST[e.P.status])+'" data-b="'+esc(e.nDoc+' av '+e.nChosen+' behov dokumentert'+(e.planned?' · planlagt lokale':''))+'"/>'; });
  return '<div class="mk-chart" id="mkChart"><svg width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" role="group" aria-label="Pris–behov-kart. '+pts.length+' alternativer. Samme innhold står i tabellen under.">'+g+marks+labels+hits+'</svg><div class="mk-tip" id="mkTip" hidden></div></div>';
}
function mkDetail(e,sc){
  const a=e.alt, P=e.P, st=v=>v==='ja'?'<span class="cst c-avklart">Ja</span>':v==='nei'?'<span class="cst c-motstridende">Nei</span>':'<span class="cst c-mangler">Ukjent</span>';
  return '<div class="mk-det" id="mkDet" tabindex="-1"><div class="mk-det-h"><div><span class="lbl">'+(a.own?'Litteraturhusets alternativ':'Alternativ')+(a.test?' · TESTDATA':'')+'</span><h3>'+esc(a.supplier)+' · '+esc(a.name)+'</h3><span class="meta">'+(a.type==='pakke'?'Pakke':'Rom')+' · '+(a.planned?'<b class="st-warn">Planlagt lokale'+(a.plannedNote?', '+esc(a.plannedNote):'')+'. Ikke i drift, og ingen tilgjengelighet er dokumentert.</b>':'Lokale i drift')+'</span></div><div class="row"><button class="btn sm" type="button" data-mked="'+esc(a.id)+'">Endre</button><button class="btn ghost sm" type="button" data-mkdrop="'+esc(a.id)+'">Ta ut av scenarioet</button><button class="btn ghost sm" type="button" id="mkDetX">Lukk detaljene</button></div></div>'+
   '<div class="mk-det-g"><div><h4>Pris for scenarioet</h4><div class="mk-scroll"><table class="dense"><thead><tr><th>Del</th><th class="n">Beløp</th><th>Status og kilde</th></tr></thead><tbody>'+(P.lines.length?P.lines.map(l=>'<tr><td>'+esc(MK_CAT[l.k])+(l.label?'<span class="s">'+esc(l.label)+'</span>':'')+'</td><td class="n">'+(l.status==='inkludert'?'<span class="meta">inkludert</span>':l.scen!=null?kr(l.scen):'<span class="st-warn">mangler</span>')+'</td><td class="s2">'+esc(MK_PST[l.status]||'')+(l.flags.length?' · '+esc(l.flags.join(', ')):'')+'<span class="s">'+esc(mkSrcTxt(l.srcO))+'</span></td></tr>').join(''):'<tr><td colspan="3" class="meta">Ingen prislinjer er registrert.</td></tr>')+'</tbody>'+
     '<tfoot><tr><td><b>Sum</b></td><td class="n"><b>'+(P.total!=null?kr(P.total):'Kan ikke regnes ut')+'</b></td><td class="s2">'+(P.total!=null?esc(MK_PST[P.status])+', '+(sc.vat==='inkl'?'inkl.':'eks.')+' mva'+(P.minApplied?' · minimumsleie '+kr(P.minimum)+' er brukt':''):'Se «Må avklares»')+'</td></tr></tfoot></table></div></div>'+
    '<div><h4>Valgte behov</h4><div class="mk-scroll"><table class="dense"><thead><tr><th>Behov</th><th>Svar</th><th>Grunnlag</th></tr></thead><tbody>'+(e.needs.length?e.needs.map(n=>'<tr><td>'+esc(n.label)+(n.must?'<span class="s">Absolutt krav</span>':'')+'</td><td>'+st(n.v)+'</td><td class="s2">'+(n.v==='ukjent'?'Ikke registrert':n.doc?'Dokumentert':'<span class="st-warn">Ikke dokumentert, teller ikke</span>')+(n.note?' · '+esc(n.note):'')+'<span class="s">'+esc(mkSrcTxt(n.src))+(n.src&&n.src.excerpt?' · «'+esc(n.src.excerpt)+'»':'')+'</span></td></tr>').join(''):'<tr><td colspan="3" class="meta">Ingen behov er valgt i scenarioet.</td></tr>')+'</tbody></table></div></div></div></div>';
}
