   (X.err?'<div class="notice err" role="alert">'+esc(X.err)+'</div>':'')+
   '<div class="row asg-btn">'+(X.id?'<button class="btn ghost danger" type="button" id="mkAltDel" style="margin-right:auto">Slett alternativet</button>':'')+'<button class="btn primary" type="button" id="mkAltSave">Lagre</button><button class="btn ghost" type="button" id="mkAltNo">Avbryt</button></div>';
  const keep=root.querySelector('.modal-b')?.scrollTop||0;
